import { internalRecorderError } from "./errors.js";
import { combineReports, publicRedactionReport, scanJsonValue } from "./scanner.js";
export function loadPublicManifestSchema() { return { $schema: "https://json-schema.org/draft/2020-12/schema", title: "Recorder manifest v2" }; }
export function validatePublicManifest(v) { if (!v || typeof v !== "object" || Array.isArray(v)) {
    throw internalRecorderError("manifest", new Error("manifest shape"));
} const m = v; if (m.version !== 2 || m.invocation.id !== m.session.id || !m.receipt || m.execution.stdio.stdout !== "pass-through" || m.execution.stdio.diagnosticTailBytes !== 4096)
    throw internalRecorderError("manifest", new Error("manifest invariant")); }
export function buildManifest(o) { if (o.child.status === "not-spawned")
    throw internalRecorderError("manifest", new Error("child missing")); const skeleton = { version: 2, archive: o.config.archive, invocation: { id: o.config.session.id }, session: { ...o.session, retention: "caller-owned-raw-not-promoted" }, execution: { argv: o.childArgv, cwd: o.config.execution.cwd, environment: o.config.execution.environment, stdin: "inherit", stdio: { stdout: "pass-through", stderr: "pass-through", diagnosticTailBytes: 4096 } }, provenance: { ...o.config.provenance, verification: "unverified" }, artifacts: o.artifacts, receipt: { toolName: o.extraction.receipt.toolName, toolCallId: o.extraction.receipt.toolCallId, artifactId: "receipt", artifactKind: o.extraction.artifactKind }, auditObservation: o.extraction.auditObservation, child: { status: o.child.status, exitCode: o.child.exitCode, signal: o.child.signal }, recorder: { status: "completed" }, redaction: { hits: [] } }; const scanned = scanJsonValue(skeleton, "manifest"); const report = combineReports(o.scanReport, scanned.report); const manifest = scanned.value; manifest.redaction.hits = publicRedactionReport(report); validatePublicManifest(manifest); return { manifest, report }; }
